import { LayoutDashboard, Lightbulb, Route, MessageSquare, StickyNote, BookOpen, Plug, Settings, Wallet, Sparkles, Search, Plus, ArrowUpRight, ArrowRight, Check, ChevronRight, X, ShieldCheck, Clock, CheckCircle2, AlertCircle, Loader2, Send, Pin, Archive, Pencil, Download, RefreshCw, Menu, GitBranch, FileText, CalendarDays, ExternalLink, Copy, History, LogOut, Target, LockKeyhole, CircleHelp } from "lucide-react";
import { CATEGORIES, PHASES, STATUS_LABELS, type Item, type Kind, type State, type Revision, type Extra } from "@/lib/types";
